contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }
    function test(address depositor, uint256 amount, uint256 r1, uint256 r2) external returns (bool) {
        require(r1 != r2 && amount > 0);
        require(address(this).balance >= amount);
        c.setRewardRate(r1);
        c.deposit{value: amount}();
        uint256 snap = c.rateSnapshot(depositor);
        c.setRewardRate(r2);
        uint256 claimed = c.claim();
        assert(claimed == amount * snap);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount, uint256 r1, uint256 r2) public payable {
        require(address(this).balance >= amount);
        c.deposit{value: amount}();
        c.setRewardRate(r1);
        uint256 snap = c.rateSnapshot(address(this));
        c.setRewardRate(r2);
        uint256 claimed = c.claim();
        assert(claimed == amount * snap);
    }
    receive() external payable {}
}
